import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "approving the replacement approves a vendor whose other documents were already approved",
    { tag: "@LIF-06" },
    async ({ apiAs, factory }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const { vendor, extractions } = await factory.vendorInReview();

      // The other two documents are approved while the vendor is still in review.
      for (const kind of ["insurance_certificate", "contract"] as const) {
        await expectStatus(
          await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
            data: { decision: "approve" },
          }),
          200,
        );
      }
      // Rejecting the W-9 sends the whole vendor back.
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
          data: { decision: "reject", note: "Tax ID does not match" },
        }),
        200,
      );

      const replacement = await factory.upload(vendor.id, "w9");
      await expect
        .poll(
          async () =>
            (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
          { message: "replacement W-9 finishes extraction", timeout: 30_000 },
        )
        .toBe("extracted");
      const replacementExtraction = await factory.extraction(replacement.id);
      expect(replacementExtraction.status, "replacement extraction awaits review").toBe("pending_review");

      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      // Act
      const approved = await expectStatus<Extraction>(
        await reviewer.post(`/api/extractions/${replacementExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );

      // Assert
      expect(approved.status).toBe("approved");
      const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
      expect(stored.status).toBe("approved");
      const audit = await expectStatus<{ items: { action: string }[] }>(
        await member.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
    },
  );
});
